window.AUTH=window.AUTH||{};window.AUTH["19-5807"]={"d":"19-5807","id":"2020/19-5807","n":"Edwards v. Vannoy","briefs":[{"k":"petitioner","label":"Brief of petitioner Thedrick Edwards","date":"2020-07-15","url":"https://www.supremecourt.gov/DocketPDF/19/19-5807/147838/20200715145538368_Edwards%20-%20Brief%20for%20Petitioner%20FINAL.pdf","side":"pet","n":74},{"k":"respondent","label":"Brief of respondent Darrel, Warden, Louisiana State Penitentiary Vannoy","date":"2020-09-28","url":"https://www.supremecourt.gov/DocketPDF/19/19-5807/155101/20200928152401607_19-5807%20Brief%20of%20Respondent.pdf","side":"res","n":68},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-10-05","url":"https://www.supremecourt.gov/DocketPDF/19/19-5807/156865/20201005161931025_19-5807bsacUnitedStates.pdf","side":"us","n":50},{"k":"reply","label":"Reply of petitioner Thedrick Edwards","date":"2020-10-28","url":"https://www.supremecourt.gov/DocketPDF/19/19-5807/158971/20201028124934570_Edwards%20Reply%20Brief%20FINAL.pdf","side":"pet","n":55}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us1r36_j4ek.pdf","tr":true,"items":[{"t":"case","label":"Allen v. Hardy","cite":"478 U.S. 255","y":1986,"id":"1985/85-6593","sc":1,"op":5,"ar":3,"sum":"The Batson rule should not be applied retroactively on collateral review of convictions that became final before Batson was announced. A decision announcing a new constitutional rule of criminal procedure is almost automatically nonretroactive where the decision explicitly overrules past precedent. A traditional factor for consideration is the purpose to be served by the new rule, with retroactive effect being …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 33, 34","1":"passim","2":"27"}},{"t":"case","label":"Am. Publ’g Co. v. Fisher","cite":"166 U.S. 464","y":1897,"id":"scdb/1896-152","sc":1,"sum":"The statute of the Territory of Utah (Compiled Laws of 1888, § 3371, as amended in 1892) providing that “ in all civil cases a verdict may be rendered on the concurrence therein of nine or more members of the.jury,” if not invalid under the Seventh Amendment to the Constitution, is so as violating the provision in the act of September 9,1850, c. 51, admitting Utah as a Territory, that “ the Constitution and laws of …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Andres v. United States","cite":"333 U.S. 740","y":1948,"id":"scdb/1947-068","sc":1,"by":{"0":"14"}},{"t":"case","label":"Apodaca v. Oregon","cite":"406 U.S. 404","y":1972,"id":"1971/69-5046","sc":1,"op":22,"ar":21,"sum":"In a close decision the Court found that the accused's right to a jury trial does not require that juries return unanimous decisions in order to convict. After reviewing the history and function of juries in American society, the Court held that the most important function of the jury is to provide \"commonsense judgment\" in evaluating the respective arguments of accused and accuser.","sumSrc":"Oyez","by":{"0":"19","1":"passim","2":"3, 6, 11"}},{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"ar":1,"sum":"The Court held that the Due Process Clause requires that any fact that increases the penalty for a crime beyond the prescribed statutory maximum, other than the fact of a prior conviction, must be submitted to a jury and proved beyond a reasonable doubt.","sumSrc":"Oyez","by":{"0":"14, 21","3":"6"}},{"t":"case","label":"Batson v. Kentucky","cite":"476 U.S. 79","y":1986,"id":"1985/84-6263","sc":1,"op":13,"ar":9,"sum":"The Court found that the prosecutor's actions violated the Sixth and Fourteenth Amendments of the Constitution.","sumSrc":"Oyez","by":{"0":"6","1":"passim","2":"27"}},{"t":"case","label":"Beard v. Banks","cite":"542 U.S. 406","y":2004,"id":"2003/02-1603","sc":1,"op":14,"sum":"In a 5-to-4 decision written by Justice Clarence Thomas, the Court found that the rule announced in Mills - that sentencing schemes could not prevent jurors from considering mitigating evidence that had not been accepted unanimously when deciding whether to apply the death penalty - was a new rule, because it was not compelled by previous Court decisions.","sumSrc":"Oyez","by":{"0":"18, 23, 31","1":"passim","2":"14, 19, 20"}},{"t":"case","label":"Betts v. Brady","cite":"316 U.S. 455","y":1942,"id":"1940-1955/316us455","sc":1,"sum":"The Court held that refusing counsel to an indigent man did not violate the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"23","3":"8"}},{"t":"case","label":"Blakely v. Washington","cite":"542 U.S. 296","y":2004,"id":"2003/02-1632","sc":1,"op":10,"sum":"The Court held that an exceptional sentence increase based on the judge's determination that Blakely had acted with \"deliberate cruelty\" violated Blakely's Sixth Amendment right to trial by jury.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Brown v. Louisiana","cite":"447 U.S. 323","y":1980,"id":"1979/79-5364","sc":1,"op":7,"sum":"The judgment is reversed, and the case is remanded. Pp. 327337; 337. 371 So. 2d 746, reversed and remanded. MR. JUSTICE BRENNAN, joined by MR. JUSTICE STEWART, MR. JUSTICE MARSHALL, and MR. JUSTICE BLACKMUN, concluded that the constitutional principle announced in Burch v. Louisiana, supra, that conviction of a nonpetty criminal offense in a state court by a nonunanimous sixperson jury violates the accused's right …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 34, 35","1":"29","2":"12, 28, 29"}},{"t":"case","label":"Burch v. Louisiana","cite":"441 U.S. 130","y":1979,"id":"1978/78-90","sc":1,"op":7,"ar":5,"sum":"The Court found that convictions by the nonunanimous six-member jury violated the Constitution.","sumSrc":"Oyez","by":{"0":"34","1":"29","2":"12, 28"}},{"t":"case","label":"Caspari v. Bohlen","cite":"510 U.S. 383","y":1994,"id":"1993/92-1500","sc":1,"op":1,"sum":"The state trial judge sentenced respondent as a persistent offender following his conviction on three robbery counts, but the Missouri Court of Appeals reversed the sentence because there was no proof of prior convictions, as is necessary to establish persistent-offender status under state law. On remand, the trial judge resentenced respondent as a persistent offender based on evidence of prior felony convictions, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"Chaidez v. United States","cite":"568 U.S. 342","y":2013,"id":"2012/11-820","sc":1,"op":1,"sum":"The Court found that the Padilla rule created an entirely new rule regarding ineffective assistance of counsel and therefore did not apply to persons whose conviction became final before its announcement.","sumSrc":"Oyez","by":{"0":"12, 17, 18","1":"passim","2":"6, 10, 12","3":"4, 5, 20"}},{"t":"case","label":"Class v. United States","cite":"138 S. Ct. 798","y":2018,"id":"2017/16-424","sc":1,"sum":"The Court held that a guilty plea alone does not waive a defendant’s right to challenge the constitutionality of his conviction on direct appeal.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Clemons v. Mississippi","cite":"494 U.S. 738","y":1990,"id":"1989/88-6873","sc":1,"sum":"At the sentencing hearing following petitioner Clemons' Mississippi capital murder conviction, the trial court instructed the jury, among other things, that, in deciding whether to impose the death penalty, it should consider the following statutory aggravating factors: (1) that the murder was committed during the course of a \"robbery for pecuniary gain,\" and (2) that it was an \"'especially heinous, atrocious or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","2":"15"}},{"t":"case","label":"Danforth v. Minnesota","cite":"552 U.S. 264","y":2008,"id":"2007/06-8273","sc":1,"op":5,"ar":1,"sum":"The Court held that the federal case law precedent, including Teague did not constrain the authority of state courts to give broader effect to new rules of criminal procedure than was required by the precedent. The precedent applied only to federal habeas corpus petitions and had no bearing on state post-conviction proceedings.","sumSrc":"Oyez","by":{"0":"14, 27, 33","1":"52","2":"16"}},{"t":"case","label":"Desist v. United States","cite":"394 U.S. 244","y":1969,"id":"1968/12","sc":1,"op":1,"sum":"The decision in Katz v. United States, 389 U. S. 347, which held that the reach of the Fourth Amendment \"cannot turn upon the presence or absence of a physical intrusion into any given enclosure,\" and that every electronic eavesdropping upon private conversations is a search and seizure which, as a general rule, can comply with constitutional standards only when authorized by a magistrate on a showing of probable …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"DeStefano v. Woods","cite":"392 U.S. 631","y":1968,"id":"1967/559","sc":1,"op":9,"ar":8,"sum":"This Court's decisions of May 20, 1968, in Duncan v. Louisiana, 391 U. S. 145, holding that the States cannot deny a request for jury trial in serious criminal cases, and Bloom v. Illinois, 391 U. S. 194, holding that the right to jury trial extends to trials for serious criminal contempts, do not apply retroactively; and since petitioners' trials were instituted before that date the Court does not reach the issues …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32, 33","1":"30, 31","2":"7, 11, 20, 21, 28","3":"4"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"sum":"The Court held that federal sentencing guidelines are binding when a district court imposes a new sentence under a revised guideline range.","sumSrc":"Oyez","by":{"0":"14, 15, 25, 33"}},{"t":"case","label":"Gideon v. Wainwright","cite":"372 U.S. 335","y":1963,"id":"1962/155","sc":1,"op":3,"sum":"The Court held that the Sixth and Fourteenth Amendments guarantee a right of legal counsel to anyone accused of a crime.","sumSrc":"Oyez","by":{"0":"11, 15, 23, 24","1":"26, 27, 35","2":"7, 19, 20","3":"8, 9"}},{"t":"case","label":"Godfrey v. Georgia","cite":"446 U.S. 420","y":1980,"id":"1979/78-6899","sc":1,"sum":"The Supreme Court held that the Georgia law was unconstitutionally vague and failed to properly distinguish between those cases that would be eligible for the death penalty and those that wouldn’t. Even accepting the law, the Court found no evidence that Godfrey’s crimes contained the elements described in the law.","sumSrc":"Oyez","by":{"0":"13","2":"16"}},{"t":"case","label":"Graham v. Collins","cite":"506 U.S. 461","y":1993,"id":"1992/91-7580","sc":1,"op":4,"sum":"A case in which the Court declined to create a new constitutional rule that would require special jury instructions to consider the mitigating circumstances of the defendant's youth and troubled family life.","sumSrc":"Oyez","by":{"0":"31","1":"9, 14, 15, 27","3":"3"}},{"t":"case","label":"Johnson v. Louisiana","cite":"406 U.S. 356","y":1972,"id":"1970/69-5035","sc":1,"op":1,"sum":"The Court held that less-than-unanimous convictions did not violate the reasonable doubt standard embodied in the Fourteenth Amendment's Due Process Clause. Justice White argued that a minority opposing conviction does not prevent the other jurors from reaching their decisions beyond a reasonable doubt. Furthermore, the presence of dissenting jurors does not indicate that the state failed to uphold this standard.","sumSrc":"Oyez","by":{"0":"14, 18, 19, 27, 28","2":"passim","3":"3"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Johnson v. Zerbst","cite":"304 U.S. 458","y":1938,"id":"scdb/1937-168","sc":1,"sum":"1. A person charged with crime in a federal court is entitled by the Sixth Amendment to the assistance of counsel for his defense.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Kansas v. Ventris","cite":"556 U.S. 586","y":2009,"id":"2008/07-1356","sc":1,"sum":"The Court found that statements obtained for the purpose of impeaching a defendant's testimony, in the absence of a knowing and voluntary waiver of the Sixth Amendment right to counsel, were admissible.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Luis v. United States","cite":"136 S. Ct. 1083","y":2016,"id":"2015/14-419","sc":1,"sum":"The Court determined that the pretrial restraining of a defendant's assets untainted by their crime that are needed to retain counsel of choice violates the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Mackey v. United States","cite":"401 U.S. 667","y":1971,"id":"1970/36","sc":1,"ar":1,"sum":"At petitioner's trial for, income tax evasion, the Gavernment used monthly wagering tax forms petitioner had filed, as required by statutei to show that the gross -amount of wagers he reported, less business expenses, exceeded the gambling profits reported on his income tax returns. Petitioner objected on the ground that-the forms were prejudicial and irrelevant, but he was convicted in 1964 and the Court of Appeals …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 22, 23, 30"}},{"t":"case","label":"Malloy v. Hogan","cite":"378 U.S. 1","y":1964,"id":"1963/110","sc":1,"ar":1,"sum":"In a 5-to-4 opinion, the Court held that the Fifth Amendment's exception from compulsory self-incrimination is protected by the Fourteenth Amendment against abridgement by a state. When determining if state officers properly obtained a confession, one must focus on whether the statements were made freely and voluntarily without any direct or implied promised or improper influence.","sumSrc":"Oyez","by":{"0":"15","3":"4"}},{"t":"case","label":"Mandel v. Bradley","cite":"432 U.S. 173","y":1977,"id":"1976/76-128","sc":1,"sum":"In appellees' action challenging the constitutionality of a Maryland statute requiring an independent candidate for statewide or federal office, in order to qualify for a position on the general election ballot, to file 70 days before the date of party primaries, nominating petitions signed by at least 3% of the State's registered voters, the three-judge District Court was not warranted in holding, on the basis of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","1":"18"}},{"t":"case","label":"Mapp v. Ohio","cite":"367 U.S. 643","y":1961,"id":"1960/236","sc":1,"op":7,"sum":"The Court decided that evidence obtained illegally may not be used against someone in a court of law by the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Maxwell v. Dow","cite":"176 U.S. 581","y":1900,"id":"scdb/1899-143","sc":1,"sum":"The decision in Hurtado v. California, 110 U. S. 516, that the words “ due process of law ” in the Fourteenth Amendment to the Constitution of the United States do not necessarily require an indictment by a grand jury in a prosecution by a State for murder, has been often affirmed, and is now reaffirmed and applied to this case.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"14","2":"11"}},{"t":"case","label":"Maynard v. Cartwright","cite":"486 U.S. 356","y":1988,"id":"1987/87-519","sc":1,"sum":"As applied in this case, the statutory aggravating circumstance was unconstitutionally vague.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12","2":"15"}},{"t":"case","label":"McDonald v. Chicago","cite":"561 U.S. 742","y":2010,"id":"2009/08-1521","sc":1,"op":2,"sum":"The Court held that the Fourteenth Amendment makes the Second Amendment's right to bear arms for the purpose of self-defense applicable in the states.","sumSrc":"Oyez","by":{"0":"15, 16, 21","1":"15, 16, 21","2":"3, 12, 15","3":"6, 7"}},{"t":"case","label":"Miller-El v. Cockrell","cite":"537 U.S. 322","y":2003,"id":"2002/01-7662","sc":1,"op":1,"sum":"The Court held that the Court of Appeals should have issued a COA to review the District Court's denial of habeas corpus relief.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Miranda v. Arizona","cite":"384 U.S. 436","y":1966,"id":"1965/759","sc":1,"op":9,"sum":"The Court held that law enforcement cannot use testimony given by anyone under interrogation while in custody without that person being informed of their legal rights.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Missouri v. Frye","cite":"566 U.S. 134","y":2012,"id":"2011/10-444","sc":1,"sum":"The Court held that the Sixth Amendment requires defense attorneys to communicate formal plea offers from the prosecution.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"O’Dell v. Netherland","cite":"521 U.S. 151","y":1997,"id":"1996/96-6867","sc":1,"op":3,"sum":"The Court held that the rule was new, and that it could not be used to disturb O'Dell's death sentence, which had been final for six years when Simmons was decided. Justice Thomas reasoned that the rule was new within the meaning of Teague v Lane, 489 U.S. 288.","sumSrc":"Oyez","by":{"0":"18, 23, 32","1":"26, 28","2":"13, 14, 17"}},{"t":"case","label":"Padilla v. Kentucky","cite":"559 U.S. 356","y":2010,"id":"2009/08-651","sc":1,"sum":"The Court held that counsel must inform a client whether or not his plea carries a risk of deportation under the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"17","1":"27"}},{"t":"case","label":"Patton v. United States","cite":"281 U.S. 276","y":1930,"id":"scdb/1929-043","sc":1,"sum":"1. After the commencement of a trial in a federal court before a jury of twelve men upon an indictment charging a crime, punishment for which may involve a penitentiary sentence, if one juror becomes incapacitated and unable to proceed further with his work as a juror, the defendant and the Government, through its official representative in charge of the case, may consent to the trial's proceeding to a finality with …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Pena-Rodriguez v. Colorado","cite":"137 S. Ct. 855","y":2017,"id":"2016/15-606","sc":1,"sum":"The Court held that the no-impeachment rule may not bar evidence of racial bias offered to prove a violation of the Sixth Amendment right to an impartial jury.","sumSrc":"Oyez","by":{"0":"15, 28, 29, 38"}},{"t":"case","label":"Ramos v. Louisiana","cite":"140 S. Ct. 1390","y":2020,"id":"2019/18-5924","sc":1,"op":128,"ar":30,"sum":"The Court held that the Fourteenth Amendment fully incorporates the Sixth Amendment’s guarantee of a unanimous verdict against the states.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Richardson v. United States","cite":"526 U.S. 813","y":1999,"id":"1998/97-8629","sc":1,"sum":"The Court held that a jury in a \"continuing criminal enterprise\" case is required to agree unanimously not only that accused committed continuing series of violations, but also which specific violations made up the continuing series.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"S. Union Co. v. United States","cite":"567 U.S. 343","y":2012,"id":"2011/11-94","sc":1,"sum":"The Court held that the rule applied in Apprendi v. New Jersey, where the Sixth Amendment’s guarantee of a jury trial requires that any fact which increases the maximum punishment for a particular crime be proved to a jury, applies to the imposition of criminal fines.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Saffle v. Parks","cite":"494 U.S. 484","y":1990,"id":"1989/88-1264","sc":1,"op":1,"sum":"Parks is not entitled to federal habeas relief. The principle he urges is a \"new rule\" of federal constitutional law that can neither be announced nor applied in a case on collateral review unless it comes within one of two narrow-and here inapplicable-exceptions. Teaqne v. Lane, 489 U. S. 288; Penry v. Lynaugh, 492 U. S. 302.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24","1":"25, 35","2":"13","3":"3"}},{"t":"case","label":"Sawyer v. Smith","cite":"497 U.S. 227","y":1990,"id":"1989/89-5809","sc":1,"op":5,"sum":"Petitioner is not entitled to federal habeas relief, because Caldwell announced a new rule, as defined by Teague, that does not come within either of the Teague exceptions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"21, 27, 29","2":"27, 32"}},{"t":"case","label":"Schiro v. Farley","cite":"510 U.S. 222","y":1994,"id":"1993/92-7549","sc":1,"sum":"At petitioner Schiro's state court trial on three counts of murder-including, in Count I, the charge that he \"knowingly\" killed the victim, and, in Count II, that he killed her while committing rape-the jury returned a verdict of guilty on Count II, but left the remaining verdict sheets blank. The trial court imposed the death sentence, finding that the State had proved the statutory aggravating factor that Schiro …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Schriro v. Summerlin","cite":"542 U.S. 348","y":2004,"id":"2003/03-526","sc":1,"op":14,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Court held that the changed announced in Ring v. Arizona was merely procedural and therefore not retroactively applicable.","sumSrc":"Oyez","by":{"0":"32, 33","1":"passim","2":"7, 17, 20, 21, 26"}},{"t":"case","label":"South Dakota v. Wayfair, Inc.","cite":"138 S. Ct. 2080","y":2018,"id":"2017/17-494","sc":1,"sum":"A case in which the Court overruled Quill Corp. v. North Dakota and National Bellas Hess, Inc. v. Department of Revenue of Illinois, holding that states may require sellers with no physical presence in the state to collect and remit sales tax for goods sold within the state.","sumSrc":"Oyez","by":{"0":"37","1":"41"}},{"t":"case","label":"State v. Edwards","cite":"51 So. 3d 27","y":2010,"court":"La.","url":"https://www.courtlistener.com/c/So.%203d/51/27/","by":{"0":"6"}},{"t":"case","label":"State v. Edwards","cite":"2009 WL 1655544","y":2009,"court":"La. Ct. App. June 12","by":{"0":"3, 4, 6"}},{"t":"case","label":"State v. Gipson","cite":"2020 WL 3427193","y":2020,"court":"La. June 3","by":{"0":"31"}},{"t":"case","label":"Stringer v. Black","cite":"503 U.S. 222","y":1992,"id":"1991/90-6616","sc":1,"sum":"In a federal habeas corpus proceeding, a petitioner whose death sentence became final before Maynard and Clemons were decided is not foreclosed by Teague from relying on those cases.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 13, 16, 18","1":"22, 39","2":"15, 16, 30","3":"4, 5"}},{"t":"case","label":"Sullivan v. Louisiana","cite":"508 U.S. 275","y":1993,"id":"1992/92-5129","sc":1,"op":1,"sum":"A constitutionally deficient reasonable-doubt instruction cannot be harmless error.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","3":"11"}},{"t":"case","label":"Thompson v. Utah","cite":"170 U.S. 343","y":1898,"id":"scdb/1897-126","sc":1,"sum":"The provision in the constitution of the State of Utah, providing for the trial of criminal cases, not capital, in courts of general jurisdiction by a jury composed of eight persons, is ex post facto in its application to felonies committed before the Territory became a State.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Timbs v. Indiana","cite":"139 S. Ct. 682","y":2019,"id":"2018/17-1091","sc":1,"op":2,"sum":"The Eighth Amendment’s Excessive Fines Clause is an incorporated protection applicable to the States under the Fourteenth Amendment’s Due Process Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 22","1":"15, 21","2":"15","3":"6"}},{"t":"case","label":"Tyler v. Cain","cite":"533 U.S. 656","y":2001,"id":"2000/00-5961","sc":1,"op":4,"sum":"The Court held that the Cage rule was not \"made retroactive to cases on collateral review by the Supreme Court.\" Justice Thomas wrote for the Court that \"[b]ecause 'made' means 'held'...it is clear that the Cage rule has not been 'made retroactive to cases on collateral review by the Supreme Court.' Cage itself does not hold that it is retroactive.","sumSrc":"Oyez","by":{"0":"30","1":"28","2":"28"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"14","3":"18"}},{"t":"case","label":"United States v. Fordice","cite":"505 U.S. 717","y":1992,"id":"1991/90-1205","sc":1,"op":1,"sum":"A state's duty is not discharged \"until it eradicates policies and practices traceable to its prior de jure dual system that continues to foster segregation.\" Race-neutral admissions are not a sufficient corrective to constitutional violations of a dual system. Different admissions criteria, and different missions for university system components, may have racially discriminatory effects perpetuating the old system.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"sum":"The trial judge's refusal to submit the question of \"materiality\" to the jury was unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"United States v. Haymond","cite":"139 S. Ct. 2369","y":2019,"id":"2018/17-1672","sc":1,"sum":"The Tenth Circuit’s judgment—that 18 U. S. C. §3583(k)’s last two sentences are unconstitutional and unenforceable—is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14"}},{"t":"case","label":"United States v. Timmreck","cite":"441 U.S. 780","y":1979,"id":"1978/78-744","sc":1,"sum":"A conviction based on a guilty plea is not subject to collateral attack when all that can be shown is a formal violation of Rule 11. Such a violation is neither constitutional nor jurisdictional. Nor can any claim reasonably be made that the error here resulted in a \"complete miscarriage of justice\" or in a proceeding \"inconsistent with the rudimentary demands of fair procedure.\" Hill v. United States, 368 U. S. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Vasquez v. Hillery","cite":"474 U.S. 254","y":1986,"id":"1985/84-836","sc":1,"sum":"The Court held that Hillery was allowed to pursue his claim in federal court because the district court was within its power to request additional evidence that did not fundamentally alter the legal claim that the state courts already considered.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Whorton v. Bockting","cite":"549 U.S. 406","y":2007,"id":"2006/05-595","sc":1,"op":15,"ar":3,"sum":"The Court ruled unanimously \"that Crawford announced a 'new rule' of criminal procedure and that this rule does not fall within the Teague exception for watershed rules.\" Justice Samuel Alito's opinion called the Crawford ruling \"flatly inconsistent\" with the prior precedents that it overruled. It was therefore a new rule of criminal procedure.","sumSrc":"Oyez","by":{"0":"12, 23, 26, 31","1":"passim","2":"passim","3":"10, 11, 20"}},{"t":"case","label":"Withrow v. Williams","cite":"507 U.S. 680","y":1993,"id":"1992/91-1030","sc":1,"op":1,"sum":"The Supreme Court held that the decision in Stone had been one of prudence rather than one of jurisdiction.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Wright v. West","cite":"505 U.S. 277","y":1992,"id":"1991/91-542","sc":1,"op":2,"sum":"The judgment is reversed, and the case is remanded. 931 F. 2d 262, reversed and remanded. JUSTICE THOMAS, joined by THE CMHEF JUSTICE and JUSTICE ScALiA, concluded that regardless of whether a federal habeas court should review state-court applications of law to fact deferentially or de novo, the trial record contains more than enough evidence to support West's conviction. Jackson repeatedly emphasizes the deference …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","3":"7, 8"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"1, 25"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"1","2":"8"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"0":"25"}},{"t":"usc","label":"28 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/28/2101","subs":["(c)"],"by":{"0":"6"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)(2)(A)"],"stext":{"head":"§2244. Finality of determination","paras":[[0,"(a) No circuit or district judge shall be required to entertain an application for a writ of habeas corpus to inquire into the detention of a person pursuant to a judgment of a court of the United States if it appears that the legality of such detention has been determined by a judge or court of the United States on a prior application for a writ of habeas corpus, except as provided in section 2255."],[0,"(b)(1) A claim presented in a second or successive habeas corpus application under section 2254 that was presented in a prior application shall be dismissed."],[0,"(2) A claim presented in a second or successive habeas corpus application under section 2254 that was not presented in a prior application shall be dismissed unless—"],[1,"(A) the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[1,"(B)(i) the factual predicate for the claim could not have been discovered previously through the exercise of due diligence; and"],[1,"(ii) the facts underlying the claim, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that, but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(3)(A) Before a second or successive application permitted by this section is filed in the district court, the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application."],[0,"(B) A motion in the court of appeals for an order authorizing the district court to consider a second or successive application shall be determined by a three-judge panel of the court of appeals."],[0,"(C) The court of appeals may authorize the filing of a second or successive application only if it determines that the application makes a prima facie showing that the application satisfies the requirements of this subsection."],[0,"(D) The court of appeals shall grant or deny the authorization to file a second or successive application not later than 30 days after the filing of the motion."],[0,"(E) The grant or denial of an authorization by a court of appeals to file a second or successive application shall not be appealable and shall not be the subject of a petition for rehearing or for a writ of certiorari."],[0,"(4) A district court shall dismiss any claim presented in a second or successive application that the court of appeals has authorized to be filed unless the applicant shows that the claim satisfies the requirements of this section."],[0,"(c) In a habeas corpus proceeding brought in behalf of a person in custody pursuant to the judgment of a State court, a prior judgment of the Supreme Court of the United States on an appeal or review by a writ of certiorari at the instance of the prisoner of the decision of such State court, shall be conclusive as to all issues of fact or law with respect to an asserted denial of a Federal right which constitutes ground for discharge in a habeas corpus proceeding, actually adjudicated by the Supreme Court therein, unless the applicant for the writ of habeas corpus shall plead and the court shall find the existence of a material and controlling fact which did not appear in the record of the proceeding in the Supreme Court and the court shall further find that the applicant for the writ of habeas corpus could not have caused such fact to appear in such record by the exercise of reasonable diligence."],[0,"(d)(1) A 1-year period of limitation shall apply to an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court. The limitation period shall run from the latest of—"],[1,"(A) the date on which the judgment became final by the conclusion of direct review or the expiration of the time for seeking such review;"],[1,"(B) the date on which the impediment to filing an application created by State action in violation of the Constitution or laws of the United States is removed, if the applicant was prevented from filing by such State action;"],[1,"(C) the date on which the constitutional right asserted was initially recognized by the Supreme Court, if the right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(D) the date on which the factual predicate of the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(2) The time during which a properly filed application for State post-conviction or other collateral review with respect to the pertinent judgment or claim is pending shall not be counted toward any period of limitation under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2244?type=usc&year=mostrecent&link-type=html"},"head":"§2244. Finality of determination","tname":"Judiciary and Judicial Procedure","by":{"0":"35, 36","3":"21"}},{"t":"usc","label":"28 U.S.C. § 2253","url":"https://www.law.cornell.edu/uscode/text/28/2253","by":{"0":"2, 8"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(d)(1)","(d)","(e)(2)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2254. State custody; remedies in Federal courts","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 8, 35","1":"passim","2":"4, 9","3":"20, 21, 21"}},{"t":"case","label":"Barron ex rel. Tiernan v. Mayor of Baltimore","cite":"7 Pet. 243","y":1833,"url":"https://www.courtlistener.com/c/Pet./7/243/","by":{"1":"15"}},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"op":1,"sum":"The Court held that, although Bousley's claim was procedurally defaulted, Bousley may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.","sumSrc":"Oyez","by":{"1":"33","3":"10"}},{"t":"case","label":"Butler v. McKellar","cite":"494 U.S. 407","y":1990,"id":"1989/88-6677","sc":1,"op":1,"ar":2,"sum":"Six weeks after Pamela Lane was murdered, petitioner Butler was arrested on an unrelated assault charge for which he retained counsel. While in custody, Butler was informed that he was a suspect in Lane's murder. After receiving Mirandawarnings, he signed waiver of rights forms and made incriminating statements about the Lane murder during interrogation. At his capital murder trial, the court denied his motion to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 21","2":"17"}},{"t":"case","label":"Cage v. Louisiana","cite":"498 U.S. 39","y":1990,"id":"1990/89-7302","sc":1,"ar":1,"sum":"The instruction was contrary to the \"beyond a reasonable doubt\" requirement articulated in Winship. The words \"substantial\" and \"grave\" suggest a higher degree of doubt than is required for acquittal under the reasonable-doubt standard. When those statements are then considered with the reference to \"moral,\" rather than evidentiary, certainty, a reasonable juror, taking the charge as a whole, could have interpreted …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Caldwell v. Mississippi","cite":"472 U.S. 320","y":1985,"id":"1984/83-6607","sc":1,"op":1,"sum":"The death sentence is vacated. 443 So. 2d 806, reversed in part and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Chen v. City of Hous.","cite":"206 F.3d 502","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/206/502/","by":{"1":"43"}},{"t":"case","label":"Cotton v. Fordice","cite":"157 F.3d 388","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/157/388/","by":{"1":"43"}},{"t":"case","label":"Crawford v. Washington","cite":"541 U.S. 36","y":2004,"id":"2003/02-9410","sc":1,"op":16,"ar":4,"sum":"The Court sided with Crawford and ruled that the Sixth Amendment's Confrontation Clause gives defendants the right to confront witnesses and cross-examine their testimony. This includes testimony police gather. The Court reasoned that the Framers intended the Confrontation Clause to prohibit out-of-court testimony as evidence against defendants.","sumSrc":"Oyez","by":{"1":"12, 27, 34, 35","2":"6, 15"}},{"t":"case","label":"Cullen v. Pinholster","cite":"563 U.S. 170","y":2011,"id":"2010/09-1088","sc":1,"sum":"The Court held that a federal court could not overturn a state criminal conviction on the basis of the facts the defendant could have alleged, but did not, in state court.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"District Attorney’s Office for Third Judicial Dist. v. Osborne","cite":"557 U.S. 52","y":2009,"id":"2008/08-6","sc":1,"sum":"The Court found that the defendant had no constitutional right to obtain post-conviction access to DNA evidence used against him at trial.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Duncan v. Louisiana","cite":"391 U.S. 145","y":1968,"id":"1967/410","sc":1,"op":4,"sum":"The Court ruled that the right to a jury trial in state prosecutions where sentences may be as long as two years were protected under the Sixth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"1":"31","2":"11, 20, 21","3":"4"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"op":2,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"Falconer v. Lane","cite":"905 F.2d 1129","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/905/1129/","by":{"1":"28"}},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"op":2,"sum":"The unanimous Court held that the Act's creation of an appellate panel, charged with reviewing all second or successive habeas applications, is not unconstitutional. The Act simply transfers the duty of habeas review from the district courts to an appellate panel.","sumSrc":"Oyez","by":{"1":"52"}},{"t":"case","label":"Flowers v. Mississippi","cite":"139 S. Ct. 2228","y":2019,"id":"2018/17-9572","sc":1,"sum":"The trial court at Flowers’ sixth murder trial committed clear error in concluding that the State’s peremptory strike of a particular black prospective juror was not motivated in substantial part by discriminatory intent.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31"}},{"t":"case","label":"Gilmore v. Taylor","cite":"508 U.S. 333","y":1993,"id":"1992/91-1738","sc":1,"op":1,"sum":"At his trial in Illinois state court, respondent Taylor admitted the killing with which he was charged, but presented evidence to support his claim that he was only guilty of voluntary manslaughter. The jury received instructions modeled after the state pattern instructions on murder and voluntary manslaughter and convicted Taylor of murder. After the conviction and sentence became final, he sought federal habeas …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Greene v. Fisher","cite":"565 U.S. 34","y":2011,"id":"2011/10-637","sc":1,"op":2,"sum":"The Court held that decisions of the Court do not constitute \"clearly established federal law\" if the decision predates the decision of a relevant state court.","sumSrc":"Oyez","by":{"1":"46, 47, 50","2":"3","3":"20"}},{"t":"case","label":"Griffith v. Kentucky","cite":"479 U.S. 314","y":1987,"id":"1986/85-5221","sc":1,"op":3,"sum":"The Court held that after a new rule had been decided in a particular case, \"the integrity of judicial review requires that we apply that rule to all similar cases pending on direct review.\" The Court reasoned that selective application of new rules violated the principle of treating similarly situated defendants on an equal basis.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Harrington v. Richter","cite":"562 U.S. 86","y":2011,"id":"2010/09-587","sc":1,"op":1,"sum":"The Court held that a defense lawyer was not deficient for failing to consult blood evidence when planning strategy for trial.","sumSrc":"Oyez","by":{"1":"47, 48"}},{"t":"case","label":"Hayden v. Paterson","cite":"594 F.3d 150","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/594/150/","by":{"1":"43"}},{"t":"case","label":"Hunter v. Underwood","cite":"471 U.S. 222","y":1985,"id":"1984/84-76","sc":1,"sum":"Section 182 violates the Equal Protection Clause of the Fourteenth Amendment. Arlington Heights v. MetropolitanHousingDevelopment Corp., 429 U. S. 252. That § 182 may have been adopted to discriminate against poor whites as well as against blacks would not render nugatory the purpose to discriminate against blacks, it being clear that the latter was a \"but-for\" motivation for adopting § 182. There is no evidence …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Johnson v. Governor of State of Fla.","cite":"405 F.3d 1214","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/405/1214/","by":{"1":"43"}},{"t":"case","label":"June Med. Servs. LLC v. Russo","cite":"140 S. Ct. 2103","y":2020,"id":"2019/18-1323","sc":1,"sum":"A case in which the Court reversed a decision by the U.S. Court of Appeals for the Fifth Circuit upholding Louisiana’s law requiring physicians who perform abortions to have admitting privileges at a local hospital because it conflicted with the Court’s binding precedent in Whole Woman’s Health v. Hellerstedt.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Lambrix v. Singletary","cite":"520 U.S. 518","y":1997,"id":"1996/96-5658","sc":1,"op":4,"sum":"Authored by Justice Antonin Scalia, the Court ruled that a prisoner whose conviction became final before the ruling, which held that if the sentencing judge in a \"weighing\" State is required to give deference to a jury's advisory sentencing recommendation, then neither the jury nor the judge is constitutionally permitted to weigh invalid aggravating circumstances, is foreclosed from relying on that decision in a federal habeas corpus proceeding.","sumSrc":"Oyez","by":{"1":"10, 20","2":"13","3":"3, 6"}},{"t":"case","label":"Mills v. Maryland","cite":"486 U.S. 367","y":1988,"id":"1987/87-5367","sc":1,"op":2,"sum":"Petitioner, a Maryland prison inmate, was tried by a state-court jury and convicted of the first-degree murder of his cellmate. In the trial's sentencing phase, the same jury found that the State had established the statutory aggravating factor that petitioner committed the murder while he was confined in a correctional institution, and marked \"no\" beside each mitigating circumstance referenced on the verdict form, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Montgomery v. Louisiana","cite":"136 S. Ct. 718","y":2016,"id":"2015/14-280","sc":1,"op":2,"ar":2,"sum":"The Court held that the Supreme Court’s decision in Miller v. Alabama, which prohibits sentencing schemes that impose a punishment of mandatory life without parole for juvenile offenders convicted of homicide, applied retroactively.","sumSrc":"Oyez","by":{"1":"25, 26, 39, 52","3":"21"}},{"t":"case","label":"Ohio v. Roberts","cite":"448 U.S. 56","y":1980,"id":"1979/78-756","sc":1,"sum":"The Court held that the purpose of the Confrontation Clause was to restrict the admission of unreliable hearsay into evidence. Generally, face-to-face confrontation is preferred as it allows the accused to probe the memory of the witness and allows the jury to take the demeanor of the witness into account when assessing the reliability of the testimony.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Quill Corp. v. North Dakota","cite":"504 U.S. 298","y":1992,"id":"1991/91-194","sc":1,"sum":"The Court also determined that North Dakota's imposition of the use tax did not constitute a breach of the Due Process Clause because the Quill Corporation had sufficient contact with the state's residents and benefited from the state's tax revenue. However, it found the use tax to be unconstitutional because it interfered with interstate commerce, rendering it a violation of the Commerce Clause.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Ring v. Arizona","cite":"536 U.S. 584","y":2002,"id":"2001/01-488","sc":1,"op":4,"ar":1,"sum":"The Court held that, because Arizona's enumerated aggravating factors operates as \"the functional equivalent of an element of a greater offense,\" the Sixth Amendment requires that they be found by a jury.","sumSrc":"Oyez","by":{"1":"28, 30","2":"21"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/Am. Exp., Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"sum":"A predispute agreement to arbitrate claims under the Securities Act of 1933 is enforceable and resolution of the claims only in a judicial forum is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23","2":"13"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"op":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"51"}},{"t":"case","label":"Schriro v. Landrigan","cite":"550 U.S. 465","y":2007,"id":"2006/05-1575","sc":1,"sum":"The Court reversed the Ninth Circuit and ruled that the District Court was within its discretion when it upheld Landrigan's sentence without granting him a new evidentiary hearing. The Justices split 5-4 with Justice Clarence Thomas writing the opinion for the majority. The Court rejected the Ninth's Circuit's holding that the District Court took out of context statements Landrigan made during his trial.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Shoop v. Hill","cite":"139 S. Ct. 504","y":2019,"id":"2018/18-56","sc":1,"sum":"Because Hill’s intellectual disability claim must be evaluated based solely on holdings of this Court that were clearly established at the time the state-court decisions were rendered, see 28 U. S. C. §2254(d)(1), the Sixth Circuit’s reliance on Moore v. Texas, 581 U. S. ___—which was handed down much later—was plainly improper.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"48"}},{"t":"case","label":"Simmons v. South Carolina","cite":"512 U.S. 154","y":1994,"id":"1993/92-9059","sc":1,"op":1,"sum":"The Court held that a state court’s refusal to instruct a jury in a sentencing trial that a defendant is ineligible for parole violated the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"State v. Hankton, 2012-0375 (La. App. 4 Cir. 8/2/13)","cite":"122 So. 3d 1028","url":"https://www.courtlistener.com/c/So.%203d/122/1028/","by":{"1":"38"}},{"t":"case","label":"State v. Krodinger, 2012-0134 (La. App. 4 Cir. 2/27/13)","cite":"128 So. 3d 270","url":"https://www.courtlistener.com/c/So.%203d/128/270/","by":{"1":"38"}},{"t":"case","label":"State v. Webb, 2013-0146 (La. App. 4 Cir. 1/30/14)","cite":"133 So. 3d 258","url":"https://www.courtlistener.com/c/So.%203d/133/258/","by":{"1":"38"}},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"op":115,"ar":44,"sum":"The judgment is affirmed. 820 F. 2d 832, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"passim","2":"passim","3":"5, 8"}},{"t":"case","label":"United States v. Johnson","cite":"40 F.3d 436","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/40/436/","by":{"1":"43"}},{"t":"case","label":"Washington v. Davis","cite":"426 U.S. 229","y":1976,"id":"1975/74-1492","sc":1,"sum":"In a 7-to-2 decision, the Court held that the procedures and written personnel test did not constitute racial discrimination under the Equal Protection Clause. The Court found that the Clause was designed to prevent official discrimination on the basis of race; laws or other official acts that had racially disproportionate impacts did not automatically become constitutional violations.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Welch v. United States","cite":"136 S. Ct. 1257","y":2016,"id":"2015/15-6418","sc":1,"op":3,"sum":"The Court held that the rule the Supreme Court announced in Johnson v. United States regarding what constitutes a violent offense for the purposes of sentencing under the Armed Career Criminal Act applies retroactively.","sumSrc":"Oyez","by":{"1":"14","2":"1","3":"20"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"sum":"In a judgment announced by Justice John Paul Stevens, the Court, with different majorities of Justices for each holding, held that Williams had been deprived of the constitutional right to the effective assistance of counsel and that the Virginia Supreme Court's refusal to set aside the Williams death sentence was a decision that was contrary to or involved an unreasonable application of clearly established federal law, as determined by the Court.","sumSrc":"Oyez","by":{"1":"47","3":"20"}},{"t":"case","label":"Wilson v. Sellers","cite":"138 S. Ct. 1188","y":2018,"id":"2017/16-6855","sc":1,"sum":"The Court decided that a federal habeas court reviewing an unexplained state court decision on the merits should “look through” that decision to the most recent related state court decision that provides a relevant rationale and presume that the unexplained decision adopted the same reasoning, and that the state may rebut that presumption by showing that the unexplained decision most likely relied on different grounds than the reasoned decision below.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Ballew v. Georgia","cite":"435 U.S. 223","y":1978,"id":"1977/76-761","sc":1,"ar":2,"sum":"The Court found that a trial by jury of less than six members violated the accused's right to a trial by jury as protected by the Sixth and Fourteenth Amendments. Justice Blackmun reasoned that small juries foster poor group deliberation.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Engle v. Isaac","cite":"456 U.S. 107","y":1982,"id":"1981/80-1430","sc":1,"sum":"Ruled in favor of Engle and stated that the respondents cannot challenge the constitutionality of the Ohio jury instructions in federal habeas corpus proceedings.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Horn v. Banks","cite":"536 U.S. 266","y":2002,"id":"2001/01-1385","sc":1,"op":2,"sum":"The Court held that the Court of Appeals committed a clear error by failing to perform a Teague analysis.","sumSrc":"Oyez","by":{"2":"9","3":"19"}},{"t":"case","label":"Lowenfield v. Phelps","cite":"484 U.S. 231","y":1988,"id":"1987/86-6867","sc":1,"sum":"At petitioner's state-court trial on charges of killing five people, the jury returned guilty verdicts on three counts of first-degree murder, an essential statutory element of which, under the circumstances, was a finding of intent \"to kill or inflict great bodily harm upon more than one person.\" At the penalty phase, in response to notes from the jury indicating difficulty in reaching a decision, the court twice …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Marks v. United States","cite":"430 U.S. 188","y":1977,"id":"1976/75-708","sc":1,"sum":"The Due Process Clause of the Fifth Amendment precludes retroactive application to petitioners of the Miller standards, to the extent that those standards may impose criminal liability for conduct not punishable under the standards announced in Memoirs v. Massachusetts, 383 U. S. 413. Bouie v. City of Columbia, 378 U. S. 347. Specifically, petitioners are entitled to jury instructions requiring the jury to acquit …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29","3":"3"}},{"t":"case","label":"Penry v. Lynaugh","cite":"492 U.S. 302","y":1989,"id":"1988/87-6177","sc":1,"op":2,"sum":"The Court partially affirmed and partially reversed the lower court's decision. Justice O'Connor argued that the jury was improperly instructed and should have been told that it could have considered Penry's mental deficiencies when imposing its sentence.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Schad v. Arizona","cite":"501 U.S. 624","y":1991,"id":"1990/90-5551","sc":1,"op":1,"sum":"In a complex decision, Souter's plurality opinion acknowledged that jury instructions offering all-or-nothing alternatives in capital cases may overstep the Due Process Clause. But Schad's jury was not faced with such a choice. His jury had been instructed on the non-capital offense of second-degree murder.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Taylor v. Louisiana","cite":"419 U.S. 522","y":1975,"id":"1974/73-5744","sc":1,"sum":"The Court held that a jury made up of a representative cross-section of the community is an essential component of the Sixth Amendment.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"United States v. Mechanik","cite":"475 U.S. 66","y":1986,"id":"1985/84-1640","sc":1,"op":1,"sum":"However diligent the defendants may have been in seeking to discover the basis for the claimed violation of Rule 6(d), the petit jury's guilty verdict rendered harmless any error in the grand jury's charging decision that may have flowed from the violation. In such case, the societal costs of retrial are far too substantial to justify setting aside the verdict simply because of an error in the grand jury proceeding. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31"}},{"t":"case","label":"United States v. Powell","cite":"469 U.S. 57","y":1984,"id":"1984/83-1307","sc":1,"op":8,"ar":4,"sum":"There is no reason to vacate respondent's telephone facilitation convictions merely because the verdicts cannot rationally be reconciled.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Williams v. Florida","cite":"399 U.S. 78","y":1970,"id":"1969/927","sc":1,"sum":"The Court held that \"the 12-man [jury] requirement cannot be regarded as an indispensable component of the Sixth Amendment.\" The Court found that the purpose of the jury trial was \"to prevent oppression by the Government,\" and that the performance of this role was not dependent on the particular number of people on the jury.","sumSrc":"Oyez","by":{"2":"14, 15"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)","(e)(1)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"2":"1, 31","3":"16"}},{"t":"rule","label":"Fed. R. Crim. P. 31","url":"https://www.law.cornell.edu/rules/frcrmp/rule_31","subs":["(a)"],"by":{"2":"1"}},{"t":"case","label":"Balzac v. Porto Rico","cite":"258 U.S. 298","y":1922,"id":"scdb/1921-084","sc":1,"sum":"1. The Act of January 28, 1915, c. 22, 38 Stat. 803, amending § 246 of the Judicial Code, and providing that writs of error from this court may be prosecuted to the supreme courts of Porto Rico and Hawaii in the same classes of cases as to the courts of last resort of the States under Ju'd. Code, § 237, meant to assimilate the jurisdiction over those territorial courts to that over the state courts and is to be …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"Espinoza v. Mont. Dep’t of Revenue","cite":"140 S. Ct. 2246","y":2020,"id":"2019/18-1195","sc":1,"sum":"The Court held a Montana state law that provides funding for education but excludes religious education options violates the Free Exercise Clause of the federal Constitution.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"Jones v. United States","cite":"527 U.S. 373","y":1999,"id":"1998/97-9361","sc":1,"sum":"The Court held that Jones was not entitled to an instruction as to the effect of jury deadlock. The Court held that the Eighth Amendment does not require such an instruction and the Court declined to exercise its supervisory powers to require such an instruction in every capital case.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"21"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"McGirt v. Oklahoma","cite":"140 S. Ct. 2452","y":2020,"id":"2019/18-9526","sc":1,"sum":"The Court held that parts of eastern Oklahoma are an Indian reservation subject to exclusive federal jurisdiction for certain crimes under the Indian Major Crimes Act.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"sum":"The Court held that proving actual innocence allows a petitioner to pursue habeas corpus relief regardless of a statute of limitations.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"Muhleisen v. Ieyoub","cite":"168 F.3d 840","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/168/840/","by":{"3":"21"}},{"t":"case","label":"Rauf v. State","cite":"145 A.3d 430","y":2016,"court":"Del.","url":"https://www.courtlistener.com/c/A.3d/145/430/","sum":"Describing Apodaca as an “odd case[],” the rationale of which “is not convincing”.","sumSrc":"brief:3","by":{"3":"7"}},{"t":"case","label":"Rice v. State","cite":"532 A.2d 1357","y":1987,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/532/1357/","by":{"3":"7"}},{"t":"case","label":"Richardson v. Marsh","cite":"481 U.S. 200","y":1987,"id":"1986/85-1433","sc":1,"sum":"The Court held that not only did the jury receive instructions not to consider the confession in assessing Marsh’s guilt, but also the confession was redacted so that there was no incriminating evidence regarding Marsh’s actions. Without the implication that the evidence in the confession was incriminating, Marsh’s Confrontation Clause rights were not violated.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Roper v. Simmons","cite":"543 U.S. 551","y":2005,"id":"2004/03-633","sc":1,"sum":"The Court held that executing minors under the death penalty is unconstitutional.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"San Remo Hotel, L.P. v. San Francisco","cite":"545 U.S. 323","y":2005,"id":"2004/04-340","sc":1,"sum":"The Court rejected the argument that whenever plaintiffs reserved their federal takings claims in state court, federal courts should review the reserved federal claims, regardless of the issues decided by the state court. Moreover, federal courts were not free to disregard the full faith and credit statute simply to guarantee that all takings plaintiffs can sue in federal court.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Solem v. Stumes","cite":"465 U.S. 638","y":1984,"id":"1983/81-2149","sc":1,"sum":"Edwardsshould not be applied retroactively, and therefore the Court of Appeals erred in evaluating the constitutionality of the police conduct in this case under the standards set out in Edwards.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"8"}},{"t":"case","label":"State v. Bybee","cite":"17 Kan. 462","y":1877,"url":"https://www.courtlistener.com/c/Kan./17/462/","by":{"3":"12"}},{"t":"case","label":"Trans World Airlines, Inc. v. Hardison","cite":"432 U.S. 63","y":1977,"id":"1976/75-1126","sc":1,"sum":"Respondent Hardison (hereafter respondent) was employed by Trans World Airlines (TWA), petitioner in No. 75-1126, in a department that operated 24 hours a day throughout the year in connection with an airplane maintenance and overhaul base. Respondent was subject to a seniority system in a collective-bargaining agreement between TWA and the International Association of Machinists & Aerospace Workers (union), …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"2"}},{"t":"case","label":"United States v. Cronic","cite":"466 U.S. 648","y":1984,"id":"1983/82-660","sc":1,"sum":"The Court held that the Court of Appeals erred by inferring that the less-than-ideal circumstances leading up to the trial negatively influenced the lawyer’s performance. The Sixth Amendment protects the right for an accused to receive effective assistance of counsel in order to protect the adversary process.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"United States v. Turrietta","cite":"696 F.3d 972","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/696/972/","sum":"Describing Apodaca as a “limited” decision resulting from “a three-way division among the justices”.","sumSrc":"brief:3","by":{"3":"7"}},{"t":"case","label":"Williams v. Cain","cite":"229 F.3d 468","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/229/468/","by":{"3":"21"}},{"t":"case","label":"COURT DOCUMENTS Br. for the State Gov’t Amici Curiae, Gideon v. Cochran","cite":"1962 WL 115122","y":1962,"court":"U.S. Nov. 23","by":{"3":"9"}},{"t":"case","label":"Opp., Casey v. United States","cite":"138 S. Ct. 2678","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/2678/","sc":1,"by":{"3":"18"}},{"t":"case","label":"U.S. Br., Tribue v. United States","cite":"929 F.3d 1326","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/929/1326/","by":{"3":"18"}}]};